import type { DoctorProfile } from './doctors';

export type OpeningDirection = 'children-therapy' | 'adult-therapy' | 'prosthodontics' | 'orthodontics';
export type ServiceSection<T> = {state:'ready';content:T} | {state:'placeholder';notice:string};
export interface ServiceInfoBlock {id:string;title:string;body:ServiceSection<readonly string[]>;}
/** Amounts are clinic-approved RUB values, not estimates generated by the template. */
export interface ServicePrice {label:string;amount:number;unit?:string;code?:string;category?:string;note?:string;}
export interface ClinicPriceList {currency:'RUB';effectiveFrom:string|null;approvedBy:string|null;document:{href:string;label:string}|null;items:readonly ServicePrice[];}
/** No sample prices; publish only an approved list. Dates are ISO calendar dates. */
export const clinicPriceList:ClinicPriceList={currency:'RUB',effectiveFrom:null,approvedBy:null,document:null,items:[]};
export interface ServicePageData {
  id:OpeningDirection;
  title:string;
  breadcrumbs:readonly {label:string;href?:string}[];
  demoNotice?:string;
  lead?:string;
  description?:ServiceSection<readonly string[]>;
  information?:readonly ServiceInfoBlock[];
  relatedDoctors?:ServiceSection<readonly DoctorProfile[]>;
  pricing?:ServiceSection<readonly ServicePrice[]>;
  appointment?:{label:string;href:string;notice?:string};
}

export function hasServiceContent<T>(section:ServiceSection<readonly T[]>|undefined,valid:(item:T)=>boolean):boolean {
  if(!section)return false;
  return section.state==='placeholder'?Boolean(section.notice.trim()):section.content.some(valid);
}
export const nonemptyServiceText=(text:string)=>Boolean(text.trim());
export function isReadyServiceDoctor(doctor:DoctorProfile):boolean {
  return Boolean(doctor.name?.trim()&&doctor.specialty?.trim()&&doctor.portrait?.src.trim()&&doctor.portrait.alt.trim());
}
export const isReadyServicePrice=(price:ServicePrice)=>Boolean(price.label.trim())&&Number.isFinite(price.amount)&&price.amount>0;
